def solve_game(n):
    # memoize states: (tuple(sorted(alice_nums)), tuple(sorted(bob_nums)), turn)
    # turn: 0 for Alice, 1 for Bob
    memo = {}

    def get_result(alice_nums, bob_nums, turn):
        state = (tuple(sorted(alice_nums)), tuple(sorted(bob_nums)), turn)
        if state in memo:
            return memo[state]

        # Check if all numbers are chosen
        if len(alice_nums) + len(bob_nums) == n:
            return "Draw"

        # Current player's possible moves
        current_nums = alice_nums if turn == 0 else bob_nums
        other_nums = bob_nums if turn == 0 else alice_nums
        all_chosen = set(alice_nums) | set(bob_nums)

        possible_moves = []
        for i in range(1, n + 1):
            if i not in all_chosen:
                # Rule (ii): cannot be consecutive to any of the player's own numbers
                is_consecutive = False
                for num in current_nums:
                    if abs(num - i) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    possible_moves.append(i)

        if not possible_moves:
            # Current player cannot move and it's not a draw
            return "Lose"

        # If any move leads to "Lose" for the other player, the current player will take it (Win)
        # If no move leads to "Lose", but some move leads to "Draw", the current player will take it (Draw)
        # Otherwise, the current player loses.

        can_draw = False
        for move in possible_moves:
            if turn == 0:
                res = get_result(alice_nums + (move,), bob_nums, 1)
            else:
                res = get_result(alice_nums, bob_nums + (move,), 0)

            if res == "Lose":
                memo[state] = "Win"
                return "Win"
            if res == "Draw":
                can_draw = True

        if can_draw:
            memo[state] = "Draw"
            return "Draw"
        else:
            memo[state] = "Lose"
            return "Lose"

    # The game result for Alice's first turn
    return get_result((), (), 0)

for n in range(1, 11):
    print(f"n={n}: {solve_game(n)}")

